#!/usr/bin/env python3
"""Exact tests for Gabor lifting generated by zero loci of binary quadratic forms.
Only Python's standard library is needed. Run: python3 quad_bent_gabor_check.py
"""
from collections import Counter


def parity(x):
    return x.bit_count() & 1


def quad(x, n, sign):
    s = sum(((x >> (2*j)) & 1) & ((x >> (2*j+1)) & 1) for j in range(n//2)) & 1
    if sign == -1:
        s ^= (x & 1) ^ ((x >> 1) & 1)
    return s


def fwht(a):
    a = a[:]
    n = len(a)
    h = 1
    while h < n:
        for i in range(0, n, 2*h):
            for j in range(i, i+h):
                x, y = a[j], a[j+h]
                a[j], a[j+h] = x+y, x-y
        h *= 2
    return a


def polar(x, n):
    y = 0
    for j in range(n//2):
        y |= ((x >> (2*j+1)) & 1) << (2*j)
        y |= ((x >> (2*j)) & 1) << (2*j+1)
    return y


def count_rank_mod(a, prime):
    b = [[x % prime for x in row] for row in a]
    rows, cols = len(b), len(b[0])
    rank = 0
    for j in range(cols):
        pivot = next((i for i in range(rank, rows) if b[i][j]), None)
        if pivot is None:
            continue
        b[rank], b[pivot] = b[pivot], b[rank]
        inv = pow(b[rank][j], -1, prime)
        b[rank][j:] = [(inv*x) % prime for x in b[rank][j:]]
        for i in range(rank+1, rows):
            c = b[i][j]
            if c:
                b[i][j:] = [(x-c*y) % prime for x,y in zip(b[i][j:],b[rank][j:])]
        rank += 1
        if rank == cols:
            return rank
    return rank


def check(n, sign):
    N = 1 << n
    t = 1 << (n//2)
    g = [1 - quad(x, n, sign) for x in range(N)]
    k = (N + sign*t) // 2
    lam = (N + 2*sign*t) // 4
    assert sum(g) == k
    assert sum((-1)**quad(x,n,sign) for x in range(N)) == sign*t
    multiplicities = Counter()
    for a in range(N):
        h = [g[x]*g[x^a] for x in range(N)]
        coeff = fwht(h)
        for b, actual in enumerate(coeff):
            if a == 0:
                expected = k if b == 0 else sign*(t//2)*(-1)**quad(polar(b,n), n, sign)
            elif parity(a & b):
                expected = 0
            elif b == 0:
                expected = lam
            elif b == polar(a,n):
                expected = (-1)**quad(a,n,sign)*lam
            else:
                expected = sign*(t//2)*(-1)**quad(polar(b,n), n, sign)
            assert actual == expected, (n,sign,a,b,actual,expected)
            multiplicities[abs(actual)] += 1
    expected = Counter({k:1,lam:2*(N-1),t//2:(N-1)*(N//2-1),0:N*(N-1)//2})
    # Coincident levels must be aggregated.
    expected=Counter()
    for val,mult in [(k,1),(lam,2*(N-1)),(t//2,(N-1)*(N//2-1)),(0,N*(N-1)//2)]:
        expected[val]+=mult
    assert multiplicities == expected, (n,sign,multiplicities,expected)
    rank = N*(N+1)//2
    assert sum(v for key,v in multiplicities.items() if key) == rank
    if n == 4:
        pairs = [(i,j) for i in range(N) for j in range(i,N)]
        matrix = []
        for a in range(N):
            for b in range(N):
                v = [g[i^a]*(-1)**parity(i & b) for i in range(N)]
                matrix.append([v[i]*v[j]*(1 if i==j else 2) for i,j in pairs])
        assert count_rank_mod(matrix, 101) == rank
    print('PASS: n=%d, Gauss sign=%+d, full projector rank=%d, levels=%s' %
          (n,sign,rank,sorted(multiplicities.items())))

if __name__=='__main__':
    for dimension in (4,6,8):
        for eps in (1,-1):
            check(dimension,eps)
    print('QUADRATIC_BENT_REAL_GABOR_EXACT_CHECKS_OK')
